function TodoList() {
  const [todos, setTodos] = React.useState([
    "Learn React"
  ]);

  function addTodo() {
    setTodos((prevTodos) => [
      ...prevTodos,
      "Build a project"
    ]);
  }

  return (
    <>
      <button onClick={addTodo}>Add Todo</button>
      {todos.map((todo) => (
        <p key={todo}>{todo}</p>
      ))}
    </>
  );
}

